source='''from collections import Counter


def transform(grid):
    height, width = len(grid), len(grid[0])
    base = Counter(value for row in grid for value in row).most_common(1)[0][0]

    horizontal = [
        r for r in range(height)
        if sum(value == base for value in grid[r]) <= 0.35 * width
    ]
    vertical = [
        c for c in range(width)
        if sum(grid[r][c] == base for r in range(height)) <= 0.35 * height
    ]

    line_colors = Counter(
        grid[r][c]
        for r in range(height)
        for c in range(width)
        if (r in horizontal or c in vertical) and grid[r][c] != base
    )
    line = line_colors.most_common(1)[0][0]

    def has_marker_on_row(r):
        return any(grid[r][c] not in (base, line) for c in vertical)

    def has_marker_on_column(c):
        return any(grid[r][c] not in (base, line) for r in horizontal)

    while len(horizontal) > 2 and not has_marker_on_row(horizontal[0]):
        horizontal = horizontal[1:]
    while len(horizontal) > 2 and not has_marker_on_row(horizontal[-1]):
        horizontal = horizontal[:-1]
    while len(vertical) > 2 and not has_marker_on_column(vertical[0]):
        vertical = vertical[1:]
    while len(vertical) > 2 and not has_marker_on_column(vertical[-1]):
        vertical = vertical[:-1]

    output = [[base for _ in range(len(vertical) - 1)] for _ in range(len(horizontal) - 1)]
    for r in range(len(horizontal) - 1):
        for c in range(len(vertical) - 1):
            corners = (
                grid[horizontal[r]][vertical[c]],
                grid[horizontal[r]][vertical[c + 1]],
                grid[horizontal[r + 1]][vertical[c]],
                grid[horizontal[r + 1]][vertical[c + 1]],
            )
            color = corners[0]
            if color not in (base, line) and all(value == color for value in corners):
                output[r][c] = color
    return output
'''
